#include <iostream>

int main() {
    int a = 17;
    int b = 5;
    int whole = 0;   // put a / b here
    int left = 0;    // put a % b here
    std::cout << a << " / " << b << " = " << whole << " remainder " << left << "\n";
    return 0;
}

hint:
Use / for how many whole times, and % for the leftover:

    int whole = a / b;
    int left = a % b;
